def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    if enemy is None:
        return (0, 0)

    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)

    w = me.weapons.get("front")
    spun = w is not None and w["type"] == "spinner" and abs(w["rpm"]) > 0.5 * w["max_rpm"]
    hot = w is not None and w["temperature"] > 140

    if not enemy.can_drive or enemy.inverted or enemy.on_side:
        if abs(b) < 30:
            return (1.0, 1.0)
        elif b > 0:
            return (0.0, 1.0)
        else:
            return (1.0, 0.0)

    if d < 0.5:
        if abs(b) < 30:
            return (-0.8, -0.8)
        elif b > 0:
            return (-0.2, 0.8)
        else:
            return (0.8, -0.2)

    if hot:
        if d > 2.0:
            if abs(b) < 20:
                return (0.8, 0.8)
            elif b > 0:
                return (0.0, 0.8)
            else:
                return (0.8, 0.0)
        else:
            if abs(b) < 20:
                return (-0.6, -0.6)
            elif b > 0:
                return (-0.2, 0.8)
            else:
                return (0.8, -0.2)

    if not spun:
        if d > 2.5:
            if abs(b) < 25:
                return (0.7, 0.7)
            elif b > 0:
                return (0.1, 0.7)
            else:
                return (0.7, 0.1)
        if abs(b) < 20:
            return (1.0, 1.0)
        elif b > 0:
            return (0.3, 1.0)
        else:
            return (1.0, 0.3)

    if d < 0.8:
        if abs(b) < 20:
            return (-0.4, -0.4)
        elif b > 0:
            return (-0.1, 0.8)
        else:
            return (0.8, -0.1)
    elif d < 2.0:
        if abs(b) < 15:
            return (1.0, 1.0)
        elif b > 0:
            return (0.4, 1.0)
        else:
            return (1.0, 0.4)
    else:
        if abs(b) < 25:
            return (1.0, 1.0)
        elif b > 0:
            return (0.2, 1.0)
        else:
            return (1.0, 0.2)

