def drive(me, enemy, arena):
    if enemy is None:
        return (1.0, 1.0)

    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)

    w = me.weapons.get("front")
    spun = w is not None and w["type"] == "spinner" and abs(w["rpm"]) > 0.8 * w["max_rpm"]

    # Work out if we are in the enemy's front arc (where their spinner lives)
    abs_to_enemy = me.heading + b
    abs_enemy_to_me = norm_angle(abs_to_enemy + 180.0)
    rel_to_enemy = norm_angle(abs_enemy_to_me - enemy.heading)
    in_front_arc = abs(rel_to_enemy) < 55.0

    # If close to a spun-up enemy spinner head-on, circle to their side
    if d < 1.0 and spun and in_front_arc:
        if abs(b) < 15:
            return (0.7, 0.7)
        elif b > 0:
            return (0.3, 1.0)
        else:
            return (1.0, 0.3)

    # Otherwise charge the enemy to keep aggression high
    if abs(b) < 25:
        return (1.0, 1.0)
    elif b > 0:
        return (0.5, 1.0)
    else:
        return (1.0, 0.5)

