def enemy_is_spinning(enemy):
    w = enemy.weapons.get("front")
    if w is None or w.get("type") != "spinner":
        return False
    return abs(w.get("rpm", 0.0)) > 0.8 * w.get("max_rpm", 1.0)

def drive(me, enemy, arena):
    if enemy is None:
        return (1.0, 1.0)

    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)

    abs_to_enemy = me.heading + b
    abs_enemy_to_me = norm_angle(abs_to_enemy + 180.0)
    rel_to_enemy = norm_angle(abs_enemy_to_me - enemy.heading)
    in_enemy_front = abs(rel_to_enemy) < 60.0

    # Don't charge straight into a spun-up enemy front spinner.
    if enemy_is_spinning(enemy) and in_enemy_front and d < 2.5:
        if abs(b) < 10:
            return (1.0, 0.2) if b >= 0 else (0.2, 1.0)
        if b > 0:
            return (0.5, 1.0)
        return (1.0, 0.5)

    # Otherwise close with the enemy.
    if abs(b) < 25:
        return (1.0, 1.0)
    if b > 0:
        return (0.5, 1.0)
    return (1.0, 0.5)

