def weapon_rpm(w):
    if w is None:
        return 0.0
    return abs(w.get("rpm", 0.0))

def drive(me, enemy, arena):
    if enemy is None or not me.can_drive:
        return (0.0, 0.0)
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    ew = (enemy.weapons or {}).get("front")
    erpm = weapon_rpm(ew)
    emax = (ew.get("max_rpm", 3000.0) if ew else 3000.0)
    spun = erpm > 0.8 * emax
    # Keep the front (spinner and heaviest armor) toward the enemy.
    if abs(b) > 30:
        if b > 0:
            return (-1.0, 1.0)
        return (1.0, -1.0)
    # If their spinner is up and we are about to meet head-on, circle to flank.
    if spun and d < 1.8 and abs(b) < 20:
        if b >= 0:
            return (0.3, 1.0)
        return (1.0, 0.3)
    return (1.0, 1.0)

